// Portable integrity controls use generated bytes, not a PostgreSQL server.
// A green result here is source qualification, never physical recovery or DACL proof.
import assert from 'node:assert/strict';
import { createHash, randomBytes } from 'node:crypto';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import test from 'node:test';
import { readRecoveryFile, recoveryPathDigest, verifyRecoveryBundle }
  from './test/disposable-recovery-bundle-guard.mjs';

const sha = data => createHash('sha256').update(data).digest('hex');
const fixedFailure = error => typeof error?.code === 'string'
  && /^recovery_bundle_[a-z_]+$/.test(error.code) && error.message === error.code;

async function fixture(t) {
  const root = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'recovery-guard-source-')));
  t.after(() => fs.rm(root, { recursive: true, force: true }));
  const sourceDirectory = path.join(root, 'source'), targetDirectory = path.join(root, 'target');
  const bundleDirectory = path.join(root, 'bundle'), keyDirectory = path.join(root, 'protected-key');
  for (const directory of [sourceDirectory, targetDirectory, bundleDirectory, keyDirectory]) {
    await fs.mkdir(directory, { mode: 0o700 });
  }
  const archivePath = path.join(bundleDirectory, 'postgresql-17-snapshot.dump');
  const keyPath = path.join(keyDirectory, 'client-vault.key');
  const manifestPath = path.join(bundleDirectory, 'manifest.json');
  // These bytes intentionally are not a restorable dump. The guard only
  // authenticates byte identity against the independently held manifest pin.
  const archiveBytes = Buffer.concat([Buffer.from('PGDMP'), randomBytes(4091)]);
  const keyBytes = Buffer.from(randomBytes(32).toString('hex') + '\n');
  await fs.writeFile(archivePath, archiveBytes, { flag: 'wx', mode: 0o600 });
  await fs.writeFile(keyPath, keyBytes, { flag: 'wx', mode: 0o600 });
  const source = { dataDirectory: sourceDirectory, port: 56001, pid: 11001, systemIdentifier: '7111111111111111111' };
  const target = { dataDirectory: targetDirectory, port: 56002, pid: 11002, systemIdentifier: '7222222222222222222' };
  const manifest = {
    schema: 'metaengine.disposable-recovery-bundle.manifest.v1',
    evidence_class: 'SYNTHETIC/STAGING', source_sha: 'a'.repeat(40),
    source: { system_identifier: source.systemIdentifier, pid: source.pid, port: source.port,
      pgdata_sha256: recoveryPathDigest(sourceDirectory) },
    dump: { file: 'postgresql-17-snapshot.dump', sha256: sha(archiveBytes), bytes: archiveBytes.length },
    key: { file: 'client-vault.key', sha256: sha(keyBytes), bytes: keyBytes.length },
    fixture: { content_sha256: 'b'.repeat(64), sequence_sha256: 'c'.repeat(64) },
    automatic_retry_allowed: false, installed_backup_verified: false,
    upgrade_authorized: false, production_authorized: false,
  };
  const manifestBytes = Buffer.from(JSON.stringify(manifest) + '\n');
  await fs.writeFile(manifestPath, manifestBytes, { flag: 'wx', mode: 0o600 });
  const options = { fixtureRoot: root, bundleDirectory, keyDirectory,
    expectedManifestSha256: sha(manifestBytes), expectedSourceHead: manifest.source_sha, source, target };
  return { root, sourceDirectory, targetDirectory, bundleDirectory, keyDirectory, archivePath,
    keyPath, manifestPath, archiveBytes, manifestBytes, manifest, options };
}

test('recovery guard qualifies only bound bundle bytes and isolated fixture paths', async t => {
  const f = await fixture(t);
  const result = await verifyRecoveryBundle(f.options);
  assert.equal(result.state, 'BUNDLE_VERIFIED');
  assert.equal(result.manifest.evidence_class, 'SYNTHETIC/STAGING');
  assert.equal(result.manifest.installed_backup_verified, false);
  assert.equal(result.manifest.upgrade_authorized, false);
  assert.equal(result.physical_restore_proven, undefined);
  assert.deepEqual(await readRecoveryFile(f.archivePath), {
    sha256: f.manifest.dump.sha256, bytes: f.manifest.dump.bytes,
  });
});

test('recovery guard rejects missing independent manifest pin without creating files', async t => {
  const f = await fixture(t);
  const before = await fs.readdir(f.root);
  await assert.rejects(verifyRecoveryBundle({ ...f.options, expectedManifestSha256: undefined }),
    { code: 'recovery_bundle_expected_binding_required' });
  assert.deepEqual(await fs.readdir(f.root), before);
});

test('recovery guard rejects a truncated dump', async t => {
  const f = await fixture(t);
  await fs.truncate(f.archivePath, 2048);
  await assert.rejects(verifyRecoveryBundle(f.options), { code: 'recovery_bundle_dump_integrity_mismatch' });
});

test('recovery guard rejects a same-length substituted dump with intact custom header', async t => {
  const f = await fixture(t);
  const changed = Buffer.from(f.archiveBytes);
  changed[1000] ^= 1;
  await fs.writeFile(f.archivePath, changed);
  assert.equal((await fs.stat(f.archivePath)).size, f.manifest.dump.bytes);
  await assert.rejects(verifyRecoveryBundle(f.options), { code: 'recovery_bundle_dump_integrity_mismatch' });
});

test('recovery guard rejects non-custom bytes even with an internally matching manifest', async t => {
  const f = await fixture(t);
  const changed = Buffer.from(f.archiveBytes);
  changed.write('OTHER', 0, 'ascii');
  await fs.writeFile(f.archivePath, changed);
  f.manifest.dump.sha256 = sha(changed);
  const bytes = Buffer.from(JSON.stringify(f.manifest));
  await fs.writeFile(f.manifestPath, bytes);
  await assert.rejects(verifyRecoveryBundle({ ...f.options, expectedManifestSha256: sha(bytes) }),
    { code: 'recovery_bundle_dump_integrity_mismatch' });
});

test('recovery guard refuses a missing key and never regenerates it', async t => {
  const f = await fixture(t);
  await fs.unlink(f.keyPath);
  await assert.rejects(verifyRecoveryBundle(f.options), { code: 'recovery_bundle_key_missing' });
  await assert.rejects(fs.lstat(f.keyPath), { code: 'ENOENT' });
});

test('recovery guard refuses a same-length format-valid substituted key', async t => {
  const f = await fixture(t);
  const replacement = Buffer.from(randomBytes(32).toString('hex') + '\n');
  await fs.writeFile(f.keyPath, replacement);
  assert.equal((await fs.stat(f.keyPath)).size, 65);
  await assert.rejects(verifyRecoveryBundle(f.options), { code: 'recovery_bundle_key_integrity_mismatch' });
});

test('recovery guard rejects a coordinated dump and manifest rewrite against the original pin', async t => {
  const f = await fixture(t);
  const changed = Buffer.from(f.archiveBytes);
  changed[2000] ^= 1;
  await fs.writeFile(f.archivePath, changed);
  f.manifest.dump.sha256 = sha(changed);
  await fs.writeFile(f.manifestPath, JSON.stringify(f.manifest));
  await assert.rejects(verifyRecoveryBundle(f.options), { code: 'recovery_bundle_manifest_digest_mismatch' });
});

test('recovery guard rejects path traversal or authority fields in a pinned manifest', async t => {
  const f = await fixture(t);
  for (const mutate of [
    value => { value.dump.file = '../postgresql-17-snapshot.dump'; },
    value => { value.key.file = path.join(f.sourceDirectory, 'client-vault.key'); },
    value => { value.upgrade_authorized = true; },
    value => { value.physical_restore_proven = true; },
    value => { value.fixture.content_sha256 = ''; },
  ]) {
    const modified = structuredClone(f.manifest);
    mutate(modified);
    const bytes = Buffer.from(JSON.stringify(modified));
    await fs.writeFile(f.manifestPath, bytes);
    await assert.rejects(verifyRecoveryBundle({ ...f.options, expectedManifestSha256: sha(bytes) }),
      { code: 'recovery_bundle_manifest_invalid' });
  }
});

test('recovery guard rejects a malformed independently pinned manifest', async t => {
  const f = await fixture(t);
  const bytes = Buffer.from('{');
  await fs.writeFile(f.manifestPath, bytes);
  await assert.rejects(verifyRecoveryBundle({ ...f.options, expectedManifestSha256: sha(bytes) }),
    { code: 'recovery_bundle_manifest_invalid' });
});

test('recovery guard binds manifest source to independent source identity and source SHA', async t => {
  const f = await fixture(t);
  for (const options of [
    { ...f.options, expectedSourceHead: 'd'.repeat(40) },
    { ...f.options, source: { ...f.options.source, pid: 11003 } },
    { ...f.options, source: { ...f.options.source, port: 56003 } },
    { ...f.options, source: { ...f.options.source, systemIdentifier: '7333333333333333333' } },
  ]) {
    await assert.rejects(verifyRecoveryBundle(options), { code: 'recovery_bundle_source_binding_mismatch' });
  }
});

test('recovery guard rejects restore to source PGDATA before any writer runs', async t => {
  const f = await fixture(t);
  await assert.rejects(verifyRecoveryBundle({ ...f.options,
    target: { ...f.options.target, dataDirectory: f.sourceDirectory } }),
  { code: 'recovery_bundle_paths_not_disjoint' });
  assert.deepEqual(await fs.readdir(f.sourceDirectory), []);
});

test('recovery guard rejects shared port, PID, system identifier and installed ports', async t => {
  const f = await fixture(t);
  for (const field of ['port', 'pid', 'systemIdentifier']) {
    await assert.rejects(verifyRecoveryBundle({ ...f.options,
      target: { ...f.options.target, [field]: f.options.source[field] } }),
    { code: 'recovery_bundle_target_not_distinct' });
  }
  for (const port of [55432, 55433, 55434]) {
    await assert.rejects(verifyRecoveryBundle({ ...f.options, target: { ...f.options.target, port } }),
      { code: 'recovery_bundle_cluster_identity_invalid' });
  }
});

test('recovery guard rejects a target inside source PGDATA', async t => {
  const f = await fixture(t);
  const nested = path.join(f.sourceDirectory, 'nested');
  await fs.mkdir(nested);
  await assert.rejects(verifyRecoveryBundle({ ...f.options,
    target: { ...f.options.target, dataDirectory: nested } }),
  { code: 'recovery_bundle_paths_not_disjoint' });
});

test('recovery guard rejects bundle and key containment within either PGDATA', async t => {
  const f = await fixture(t);
  await assert.rejects(verifyRecoveryBundle({ ...f.options, keyDirectory: f.sourceDirectory }),
    { code: 'recovery_bundle_paths_not_disjoint' });
  await assert.rejects(verifyRecoveryBundle({ ...f.options, bundleDirectory: f.targetDirectory }),
    { code: 'recovery_bundle_paths_not_disjoint' });
  await assert.rejects(verifyRecoveryBundle({ ...f.options, keyDirectory: f.bundleDirectory }),
    { code: 'recovery_bundle_paths_not_disjoint' });
});

test('recovery guard rejects an existing target outside the private fixture root', async t => {
  const f = await fixture(t);
  const outside = await fs.realpath(await fs.mkdtemp(path.join(os.tmpdir(), 'recovery-guard-outside-')));
  t.after(() => fs.rm(outside, { recursive: true, force: true }));
  await assert.rejects(verifyRecoveryBundle({ ...f.options,
    target: { ...f.options.target, dataDirectory: outside } }),
  { code: 'recovery_bundle_fixture_scope_invalid' });
});

test('recovery guard rejects a real directory symlink or Windows junction ancestor', async t => {
  const f = await fixture(t);
  const alias = path.join(f.root, 'key-alias');
  await fs.symlink(f.keyDirectory, alias, process.platform === 'win32' ? 'junction' : 'dir');
  await assert.rejects(verifyRecoveryBundle({ ...f.options, keyDirectory: alias }),
    { code: 'recovery_bundle_directory_alias' });
  await assert.rejects(readRecoveryFile(path.join(alias, 'client-vault.key')), fixedFailure);
});

test('recovery guard rejects real hardlinks to dump, key and manifest', async t => {
  const f = await fixture(t);
  for (const file of [f.archivePath, f.keyPath, f.manifestPath]) {
    const alias = path.join(f.root, 'hardlink-control');
    await fs.link(file, alias);
    try {
      assert.equal((await fs.lstat(file)).nlink, 2);
      await assert.rejects(verifyRecoveryBundle(f.options), { code: 'recovery_bundle_file_untrusted' });
    } finally { await fs.unlink(alias); }
  }
  assert.equal((await verifyRecoveryBundle(f.options)).state, 'BUNDLE_VERIFIED');
});

test('recovery guard rejects unknown filesystem readback without paths in the error', async t => {
  const f = await fixture(t);
  const unknownPath = path.join(f.root, 'private-path-not-for-diagnostics');
  await assert.rejects(verifyRecoveryBundle({ ...f.options,
    target: { ...f.options.target, dataDirectory: unknownPath } }), error => {
    assert.equal(fixedFailure(error), true);
    assert.equal(error.message.includes(unknownPath), false);
    return true;
  });
});
